const int n  = 10;
const float radius = .1;

const vec4 line_col = vec4(0., 0., 0., 1.);
const vec4 bg_col = vec4(.5, .5, .5, 1.);

vec2 getPos(int i) {
    return vec2(float(i)*.1+.05, .5);
}

float getPointsDist(vec2 uv) {
    float ratio = iResolution.x/iResolution.y;

    float min_d2 = -1.;
    for (int i = 0; i < n; i++) {
        vec2 pos = getPos(i);
        vec2 diff = vec2((pos.x-uv.x)*ratio, pos.y-uv.y);
        float d2 = dot(diff, diff);
        if (d2 < min_d2 || min_d2 == -1.)
            min_d2 = d2;
    }

    return sqrt(min_d2);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    float d = getPointsDist(uv);
    float t = 1. - pow(1.-d/radius, 3.);
    if (t > 1.) t = 1.;

    fragColor = line_col + (bg_col-line_col)*t;
}
